def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    affordable_threats = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                affordable_threats.append(min(float(bid), float(opp.get('budget', 0))))

    if not alive:
        return float(max(0, min(budget, DAILY_SALARY * 0.35)))

    strongest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_affordable = max(affordable_threats) if affordable_threats else 0.0

    scarcity = WATER_REQ / supply
    urgent = (hp <= 3) or (no_water_days >= 1)
    critical = (hp <= 2) or (no_water_days >= 2)
    ample_supply = supply >= 22
    tight_supply = supply <= 17

    if critical:
        bid = max(DAILY_SALARY * 1.05, strongest_affordable + 2.0)
    elif urgent:
        bid = max(DAILY_SALARY * 0.9, strongest_affordable + 1.5)
    else:
        if ample_supply:
            bid = max(DAILY_SALARY * 0.28, strongest_affordable * 0.55)
        elif tight_supply:
            if strongest_prev >= 160:
                bid = DAILY_SALARY * 0.62
            elif strongest_prev >= 110:
                bid = max(DAILY_SALARY * 0.72, strongest_affordable + 1.0)
            else:
                bid = DAILY_SALARY * 0.68
        else:
            if strongest_prev >= 170:
                bid = DAILY_SALARY * 0.45
            elif strongest_prev >= 120:
                bid = max(DAILY_SALARY * 0.63, strongest_affordable + 1.0)
            else:
                bid = DAILY_SALARY * (0.52 + 0.18 * scarcity)

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.92
    if day >= 8 and urgent:
        bid *= 1.08

    min_safe = 0.0
    if critical:
        min_safe = DAILY_SALARY * 0.85
    elif urgent:
        min_safe = DAILY_SALARY * 0.6

    bid = max(min_safe, bid)
    bid = min(budget, bid)
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    potential_winners = int(day_context['supply'] // WATER_REQ)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = 0
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

    current_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 1:
        current_bid = DAILY_SALARY * 1.2
    elif my_status['hp'] == 2:
        current_bid = DAILY_SALARY * 1.0
    elif my_status['hp'] == 3:
        current_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 5:
        current_bid = DAILY_SALARY * 0.8

    if my_status['hp'] > 3:
        if max_prev_bid > DAILY_SALARY * 0.8:
            if num_alive_opponents + 1 > potential_winners:
                current_bid = max(current_bid, max_prev_bid + 5)
            else:
                current_bid = max(current_bid, max_prev_bid + 2)
        elif max_prev_bid > DAILY_SALARY * 0.5:
            current_bid = max(current_bid, max_prev_bid + 1)
        elif max_prev_bid > 0:
            current_bid = max(current_bid, DAILY_SALARY * 0.4, max_prev_bid + 1)
        else:
            if num_alive_opponents + 1 > potential_winners:
                current_bid = DAILY_SALARY * 0.7
            else:
                current_bid = DAILY_SALARY * 0.5

    final_bid = min(my_status['budget'], current_bid)

    return max(0.0, final_bid)
